SELECT i.id AS order_item_id, i.order_id, i.product_id, i.title, i.sku, i.qty, i.price, i.art_img, (SELECT COUNT(*) FROM product_reviews r WHERE r.order_item_id = i.id) AS reviewed FROM order_items i WHERE i.order_id IN
#{oid}
ORDER BY i.id

